// Independent re-check: different accumulation approach + verify counts and no non-numeric tokens
const files = ["data/a.txt","data/b.txt","data/c.txt","data/d.txt","data/e.txt"];
let total = 0, count = 0, bad = [];
for (const f of files) {
  const lines = read_text({path: f}).split("\n").filter(l => l.trim() !== "");
  let s = 0;
  for (const l of lines) {
    const v = Number(l.trim());
    if (!Number.isInteger(v)) bad.push(f + ":" + l);
    s += v;
  }
  count += lines.length;
  total += s;
  console.log(f, "lines=" + lines.length, "sum=" + s, "avg=" + (s/lines.length).toFixed(1));
}
console.log("bad tokens:", bad);
console.log("count=" + count, "TOTAL=" + total);

const files = glob({pattern: "data/**/*.txt"});
