  const bad = nums.filter(n => Number.isNaN(n));
  const s = nums.reduce((a,b)=>a+b,0);
  per[f] = {count: nums.length, sum: s, nonNumeric: bad.length};
  grand += s;
}
console.log(JSON.stringify({files, per, grand}, null, 2));
// Independent check: parse via whitespace splitting and sum using digit accumulation
const files = ["data/a.txt","data/b.txt","data/c.txt","data/d.txt","data/e.txt"];
let grand = 0;
for (const f of files) {
  const t = read_text({path: f});
  const tokens = t.split(/\s+/).filter(s => s.length);
  let s = 0, n = 0;
  for (const tok of tokens) {
    let v = 0;
    for (const ch of tok) v = v * 10 + (ch.charCodeAt(0) - 48);
    s += v; n++;
  }
  console.log(f, n, s);
  grand += s;
}
console.log("grand", grand);

