const files = ["data/a.txt","data/b.txt","data/c.txt","data/d.txt","data/e.txt"];
let total = 0, counts = {}, details = {};
for (const f of files) {
  const t = read_text({path: f});
  const lines = t.split("\n").filter(l => l.trim() !== "");
  const nums = lines.map(l => Number(l.trim()));
  const bad = nums.filter(n => Number.isNaN(n));
  counts[f] = nums.length;
  details[f] = nums.reduce((a,b)=>a+b,0);
  total += details[f];
  if (bad.length) details[f+"_bad"] = bad;
}
console.log(JSON.stringify({counts, details, total}, null, 2));
